PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sf: <http://www.opengis.net/ont/sf#>
PREFIX hydrorwth: <https://hydro-knowledge-graph-f48785.pages.rwth-aachen.de/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catchment ?catchmentLabel
WHERE {
  GRAPH <hydroturtle/camels_gb> {
    # Find the catchment with the highest total precipitation between 2012 and 2015
    {
      SELECT ?maxCatchment (MAX(?precip) AS ?maxPrecip)
      WHERE {
        ?maxCatchment a hyobs:Catchment ;
                      hydrorwth:hasMeanDailyPrecip ?precip .
        # Assume precipitation values are associated with a year or period; filter for 2012-2015 if possible
        # If precipitation is a literal with a time range, filter accordingly
        # Otherwise, this will select the max overall
      }
      GROUP BY ?maxCatchment
      ORDER BY DESC(?maxPrecip)
      LIMIT 1
    }
    # Find all catchments that share a boundary with the max precipitation catchment
    ?catchment a hyobs:Catchment ;
               sf:touches ?maxCatchment .
    OPTIONAL { ?catchment rdfs:label ?catchmentLabel }
    FILTER(?catchment != ?maxCatchment)
  }
}

actual_sparql:
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX geo:  <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>

SELECT ?topCatchment ?topTotalPrecip ?neighborCatchment
WHERE {
  GRAPH <hydroturtle/camels_gb> {
    {
      SELECT ?topCatchment (SUM(xsd:decimal(?precVal)) AS ?topTotalPrecip)
      WHERE {
        ?sensor a sosa:Sensor ;
                hyobs:monitorsCatchment ?topCatchment .

        ?obs a sosa:Observation ;
            sosa:observedProperty envthes:30106 ;
            sosa:madeBySensor ?sensor ;
            sosa:resultTime ?t ;
            sosa:hasResult ?res .

        ?res qudt:numericValue ?precVal .

        FILTER(?t >= "2012-01-01"^^xsd:date &&
              ?t <  "2016-01-01"^^xsd:date)
      }
      GROUP BY ?topCatchment
      ORDER BY DESC(?topTotalPrecip)
      LIMIT 1
    }

    ?topCatchment geo:hasGeometry ?g1 .
    ?g1 geo:asWKT ?wkt1 .

    ?neighborCatchment a envthes:30212.
    ?neighborCatchment geo:hasGeometry ?g2 .
    ?g2 geo:asWKT ?neighborWkt .

    FILTER(?neighborCatchment != ?topCatchment)
    FILTER(bif:st_intersects(?wkt1, ?neighborWkt, 0))
  }
}

