  GRAPH <hydroturtle/camels_gb> {
    {
      SELECT ?stationMax ?geomMax (MAX(?maxElev) AS ?highestElevation)
      WHERE {
        ?stationMax a hyobs:GaugingStation ;
                    hyobs:maxElevation ?maxElev ;
                    geo:hasGeometry ?geomMax .
      }
      GROUP BY ?stationMax ?geomMax
      ORDER BY DESC(?highestElevation)
      LIMIT 1
    }
    {
