      WHERE {
        ?stationMin a hyobs:GaugingStation ;
                    hyobs:minElevation ?minElev ;
                    geo:hasGeometry ?geomMin .
      }
      GROUP BY ?stationMin ?geomMin
      ORDER BY ASC(?lowestElevation)
      LIMIT 1
    }
    BIND(geof:distance(?geomMax, ?geomMin, uom:metre) AS ?distance)
    ?distance qudt:numericValue ?distanceValue .
  }
}

